const I18N={};for(const l in I18N_RAW){I18N[l]={};I18N_KEYS.forEach((k,i)=>I18N[l][k]=I18N_RAW[l][i]);}
function detectLang(){const q=new URLSearchParams(location.search).get('lang');let saved=null;try{saved=localStorage.getItem('kbm_lang');}catch(e){}
  const cands=[q,saved,...(navigator.languages||[]),navigator.language].filter(Boolean);
  for(const c of cands){const l=c.toLowerCase();if(l.startsWith('tl')||l.startsWith('fil'))return 'fil';const b=l.split('-')[0];if(I18N[b])return b;}
  return 'en';}
let LANG=detectLang();
function T(k){return (I18N[LANG]&&I18N[LANG][k])||I18N.en[k]||k;}
